export * from './result.ts';
export * from './note-store.ts';
export * from './search.ts';
import { type Result, ok, err } from './result.ts';

export interface Note { id: number; title: string; body: string }

export class NoteStore {
  private notes = new Map<number, Note>();
  private nextId = 1;

  add(title: string, body: string): Result<Note> {
    if (!title.trim()) return err('title required');
    const note = { id: this.nextId++, title, body };
    this.notes.set(note.id, note);
    return ok(note);
  }

  get(id: number): Result<Note> {
    const n = this.notes.get(id);
    return n ? ok(n) : err('not found');
  }

  list(): Note[] {
    return [...this.notes.values()];
  }
}
export type Result<T> = { ok: true; value: T } | { ok: false; error: string };
export const ok = <T>(value: T): Result<T> => ({ ok: true, value });
export const err = <T = never>(error: string): Result<T> => ({ ok: false, error });
import type { Note } from './note-store.ts';
import { type Result, ok, err } from './result.ts';

export function searchNotes(notes: Note[], term: string): Result<Note[]> {
  if (!term) return err('term required');
  const t = term.toLowerCase();
  return ok(notes.filter((n) => n.title.toLowerCase().includes(t) || n.body.toLowerCase().includes(t)));
}
