import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import type { AddressInfo } from 'node:net';
import { createServer } from '../src/http-server.ts';
import { NoteStore } from '../src/note-store.ts';

async function withServer(
  fn: (url: string, logs: string[], store: NoteStore) => Promise<void>,
  store: NoteStore = new NoteStore(),
): Promise<void> {
  const logs: string[] = [];
  const server = createServer({ store, log: (l: string) => logs.push(l) });
  await new Promise<void>((r) => server.listen(0, r));
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  try {
    await fn(url, logs, store);
  } finally {
    await new Promise((r) => server.close(r));
    server.closeAllConnections();
  }
}

const post = (url: string, body: string) =>
  fetch(`${url}/notes`, { method: 'POST', body, headers: { 'content-type': 'application/json' } });

test('AC-1 POST /notes creates a note', async () => {
  await withServer(async (url) => {
    const res = await post(url, JSON.stringify({ title: 'a', body: 'b' }));
    assert.equal(res.status, 201);
    assert.match(res.headers.get('content-type') ?? '', /application\/json/);
    const n = await res.json();
    assert.equal(n.title, 'a');
    assert.equal(n.body, 'b');
    assert.ok(Number.isInteger(n.id) && n.id > 0);
  });
});

test('AC-2 empty or whitespace title is 400 and not stored', async () => {
  await withServer(async (url) => {
    for (const title of ['', '   ']) {
      const res = await post(url, JSON.stringify({ title, body: 'b' }));
      assert.equal(res.status, 400);
      assert.deepEqual(await res.json(), { error: 'title required' });
    }
    assert.deepEqual(await (await fetch(`${url}/notes`)).json(), []);
  });
});

