import type { NoteStore } from './note-store.ts';
import { type Result, ok, err } from './result.ts';
import { handleRequest } from './notes-api.ts';
import { toHttpResponse, type HttpResponse } from './http-status.ts';
import { formatLogLine } from './request-log.ts';

const MAX_BODY = 1024 * 1024;

export interface ServerDeps { store: NoteStore; log: (line: string) => void }

async function readBody(req: http.IncomingMessage): Promise<Result<unknown>> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > MAX_BODY) return err('invalid body');
    chunks.push(chunk as Buffer);
  }
  if (size === 0) return ok(undefined);
  try {
    return ok(JSON.parse(Buffer.concat(chunks).toString('utf8')));
  } catch {
    return err('invalid body');
  }
}

async function respond(deps: ServerDeps, req: http.IncomingMessage, url: URL): Promise<HttpResponse> {
  try {
    const body = await readBody(req);
    return toHttpResponse(handleRequest(deps.store, {
      method: req.method ?? 'GET',
      path: url.pathname,
      query: url.searchParams,
      body,
    }));
  } catch {
    return { status: 500, json: { error: 'internal error' } };
  }
}

export function createServer(deps: ServerDeps): http.Server {
  return http.createServer((req, res) => {
    const start = performance.now();
    const url = new URL(req.url ?? '/', 'http://localhost');
    void respond(deps, req, url).then(({ status, json }) => {
      res.once('finish', () => {
        deps.log(formatLogLine(req.method ?? 'GET', url.pathname, status, performance.now() - start));
      });
      res.writeHead(status, { 'content-type': 'application/json' });
      res.end(JSON.stringify(json));
    });
  });
}
