import type { AddressInfo } from 'node:net';
import { createServer } from '../src/http-server.ts';
import { NoteStore } from '../src/note-store.ts';

async function withServer(
  fn: (url: string, logs: string[], store: NoteStore) => Promise<void>,
  store: NoteStore = new NoteStore(),
): Promise<void> {
  const logs: string[] = [];
  const server = createServer({ store, log: (l: string) => logs.push(l) });
  await new Promise<void>((r) => server.listen(0, r));
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  try {
    await fn(url, logs, store);
  } finally {
    await new Promise((r) => server.close(r));
    server.closeAllConnections();
  }
}

