import { type Note, NoteStore } from './note-store.ts';
import { searchNotes } from './search.ts';

export interface ApiRequest {
  method: string;
  path: string;
  query: URLSearchParams;
  body: Result<unknown>;
}
export interface ApiResult {
  created: boolean;
  result: Result<unknown>;
}

type Handler = (store: NoteStore, req: ApiRequest, params: string[]) => Result<unknown>;
interface Route { method: string; pattern: RegExp; handler: Handler; created?: boolean }

const isNoteInput = (v: unknown): v is { title: string; body: string } =>
  typeof v === 'object' && v !== null && typeof (v as Note).title === 'string' && typeof (v as Note).body === 'string';

const createNote: Handler = (store, req) => {
  if (!req.body.ok) return err('invalid body');
  if (!isNoteInput(req.body.value)) return err('invalid body');
  return store.add(req.body.value.title, req.body.value.body);
};

const getNote: Handler = (store, _req, [id]) => {
  if (!/^\d+$/.test(id)) return err('not found');
  return store.get(Number(id));
};

const search: Handler = (store, req) => searchNotes(store.list(), req.query.get('q') ?? '');

const routes: Route[] = [
  { method: 'GET', pattern: /^\/health$/, handler: () => ok({ status: 'ok' }) },
  { method: 'POST', pattern: /^\/notes$/, handler: createNote, created: true },
  { method: 'GET', pattern: /^\/notes$/, handler: (store) => ok(store.list()) },
  { method: 'GET', pattern: /^\/notes\/([^/]+)$/, handler: getNote },
  { method: 'GET', pattern: /^\/search$/, handler: search },
];

export function handleRequest(store: NoteStore, req: ApiRequest): ApiResult {
  for (const route of routes) {
    const m = route.method === req.method ? route.pattern.exec(req.path) : null;
    if (m) return { created: route.created === true, result: route.handler(store, req, m.slice(1)) };
  }
  return { created: false, result: err('not found') };
}
