import { type Result, ok, err } from './result.ts';

export function searchNotes(notes: Note[], term: string): Result<Note[]> {
  if (!term) return err('term required');
  const t = term.toLowerCase();
  return ok(notes.filter((n) => n.title.toLowerCase().includes(t) || n.body.toLowerCase().includes(t)));
}
