{"type":"text","file":{"filePath":"/Users/cwijayasundaragmail.com/Documents/learning_101/run-brownfield3/.daylight/worktrees/t2/src/http-status.ts","content":"import type { ApiResult } from './notes-api.ts';

export interface HttpResponse { status: number; json: unknown }

const errorStatus: Record<string, number> = {
  'title required': 400,
  'term required': 400,
  'invalid body': 400,
  'not found': 404,
};

export function toHttpResponse(r: ApiResult): HttpResponse {
  if (r.result.ok) return { status: r.created ? 201 : 200, json: r.result.value };
  const status = errorStatus[r.result.error] ?? 500;
  const error = status === 500 ? 'internal error' : r.result.error;
  return { status, json: { error } };
}
